def carry_over_data(apps, schema_editor):
    """Map the old statuses onto stages and keep any project description as a first task."""
    Project = apps.get_model("timesheets", "Project")
    ProjectTask = apps.get_model("timesheets", "ProjectTask")
    Project.objects.filter(status="active").update(status="schematic")
    for project in Project.objects.exclude(description=""):
        text = " ".join(project.description.split())
        ProjectTask.objects.create(project=project, name=text[:200], position=0)


